css:
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;700&display=swap');

:root {
  --bg-main: #0a0a0a;
  --bg-card: #161616;
  --bg-header: #0a0a0a;
  --accent: #00ff9d;
  --text-main: #ffffff;
  --text-gray: #a0a0a0;
  --border-color: #333333;
  --font-main: 'Space Grotesk', sans-serif;
  --font-heading: 'Space Grotesk', sans-serif;
  --shadow-sm: 8px 8px 0px #00ff9d;
  --radius: 20px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body { 
  font-family: var(--font-main); 
  background-color: var(--bg-main); 
  color: var(--text-gray); 
  line-height: 1.6; 
  display: flex; 
  flex-direction: column; 
  min-height: 100vh; 
}

a { text-decoration: none; color: inherit; transition: 0.3s; }
a:hover { color: var(--accent); letter-spacing: 1px; }

h1, h2, h3, h4 { color: var(--text-main); font-family: var(--font-heading); font-weight: 700; letter-spacing: -1px; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; width: 100%; }

.site-header { background: var(--bg-header); padding: 40px 0; }

.header-top { display: flex; justify-content: space-between; align-items: center; max-width: 1200px; margin: 0 auto; padding: 0 20px;}

.logo { font-size: 2.5rem; color: var(--text-main); font-family: var(--font-heading); font-weight: 700; text-transform: uppercase; border: 4px solid var(--accent); padding: 5px 15px; }

.nav-links { display: flex; gap: 30px; margin-top: 0; flex-wrap: wrap; }
.nav-links a { font-weight: 700; text-transform: uppercase; font-size: 0.9rem; border-bottom: 2px solid transparent; }
.nav-links a:hover { border-color: var(--accent); }

.bottom-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 40px; margin: 40px 0; }

.post-thumb-card { 
  background: var(--bg-card); 
  padding: 30px; 
  border: 2px solid var(--border-color); 
  border-radius: var(--radius); 
  box-shadow: 6px 6px 0px var(--border-color);
  display: flex; 
  flex-direction: column; 
  justify-content: space-between; 
  min-height: 250px; 
  transition: 0.3s; 
}

.post-thumb-card:hover { transform: translate(-4px, -4px); box-shadow: 10px 10px 0px var(--accent); border-color: var(--accent); }

.cat-badge { 
  background: transparent; 
  color: var(--accent); 
  border: 1px solid var(--accent);
  padding: 2px 10px; 
  font-size: 0.7rem; 
  text-transform: uppercase; 
  display: inline-block; 
  margin-bottom: 15px; 
  border-radius: 5px;
  font-weight: bold;
}

.post-thumb-title { font-size: 1.4rem; line-height: 1.2; color: var(--text-main); }

.post-container { 
  max-width: 800px; 
  margin: 40px auto; 
  background: var(--bg-card); 
  padding: 60px; 
  border-left: 8px solid var(--accent);
}

.post-h1 { font-size: 3rem; margin-bottom: 30px; }

.post-meta-info { display: flex; align-items: center; gap: 15px; margin-bottom: 30px; border-top: 1px solid var(--border-color); border-bottom: 1px solid var(--border-color); padding: 20px 0; }

.post-meta-info img { width: 60px; height: 60px; border-radius: 0; filter: grayscale(100%); }

.post-content { font-size: 1.2rem; line-height: 1.7; }
.post-content h2 { margin: 50px 0 20px; font-size: 2rem; }
.post-content p { margin-bottom: 25px; }
.post-content ul { margin: 0 0 25px 30px; }
.post-content a { color: var(--accent); text-decoration: none; border-bottom: 1px dashed var(--accent); }

.pagination { display: flex; justify-content: center; gap: 15px; margin: 60px 0; }
.page-link { width: 50px; height: 50px; display: flex; align-items: center; justify-content: center; background: var(--bg-card); border: 2px solid var(--border-color); font-weight: bold; border-radius: 50%; }
.page-link.active { background: var(--accent); color: var(--bg-main); border-color: var(--accent); }

.site-footer { background: var(--bg-header); padding: 60px 0; border-top: 2px solid var(--border-color); text-align: center; margin-top: auto; text-transform: uppercase; font-size: 0.8rem; letter-spacing: 2px; }
